'use strict';

var Float64Results = require( '@stdlib/ml/base/kmeans/results/float64' );
var algorithmResolveEnum = require( '@stdlib/ml/base/kmeans/algorithm-resolve-enum' );
var metricResolveEnum = require( '@stdlib/ml/base/kmeans/metric-resolve-enum' );
var res2json = require( './../lib' );

var results = new Float64Results();
results.replicates = 4;
results.replicate = 2;
results.metric = metricResolveEnum( 'sqeuclidean' );
results.iterations = 10;
results.algorithm = algorithmResolveEnum( 'lloyd' );
results.inertia = 3.28;
results.k = 4;
results.samples = 10;
results.features = 3;

var o = res2json( results );
console.log( o );
